document.addEventListener('workflow:appearance',()=>{state.theme=document.documentElement.dataset.uiTheme==='light'?'light':'dark';if(view==='editor')paintWave(waveBuffer);});window.addEventListener('resize',()=>{if(view==='editor'){paintWave(waveBuffer);updateTrims();}else if(view==='production'&&state.compactQueue==null&&document.querySelector('#main .page')?.classList.contains('compact-batch')!==(innerHeight<850))renderProduction();});window.addEventListener('beforeunload',e=>{saveNow();if(exporting){e.preventDefault();e.returnValue='';}});let lastTick=performance.now();setInterval(()=>{const now=performance.now();engine.tick(now-lastTick);lastTick=now;updateProduction();},120);void init().catch(error=>{notify('Chưa mở được Video hàng loạt: '+error.message,true);console.error(error);});
